begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,actor_id uuid,batch_id uuid,model_template jsonb,classification jsonb,receipt jsonb);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),'{"model":"fixture-model","systemPrompt":"Fixture system prompt","promptVersion":"analysis-v3","taxonomyVersion":"multifamily-v1","policyVersion":"reviewflow-policy-v1","providerBaseUrl":"https://example.invalid/v1","temperature":0.2,"maxTokens":900}',null,null);
insert into auth.users(id,email,raw_user_meta_data) select actor_id,'batch-'||actor_id::text||'@fixture.invalid','{}'::jsonb from fixture;
update public.profiles set org_id='22222222-2222-2222-2222-222222222222',role='manager' where id=(select actor_id from fixture);
insert into public.properties(id,org_id,name) select property_id,'22222222-2222-2222-2222-222222222222','ReviewFlow batch rollback fixture' from fixture;
insert into public.reviews(property_id,platform,platform_review_id,review_text,reviewer_name,rating,response_status) select property_id,'other','batch-review-'||n,'The pool was clean.','Fixture reviewer',5,'pending' from fixture cross join generate_series(1,105) n;
update fixture set classification=jsonb_build_object('sentiment','positive','sentimentScore',0.8,'topics',array['amenities'],'journeyStage','residency','issueDomains',array['amenities'],'severity','low','riskClass','routine','policyClass','standard','isUrgent',false,'confidence',0.9,'summary','The reviewer liked the clean pool.','recommendedAction','Thank the reviewer.','evidence',jsonb_build_array(jsonb_build_object('claim','Clean pool','quote','The pool was clean.')),'policy',jsonb_build_object('requiresHumanReview',false,'autoActionEligible',true,'flags','[]'::jsonb),'provenance',jsonb_build_object('model','fixture-model','promptVersion','analysis-v3','taxonomyVersion','multifamily-v1','policyVersion','reviewflow-policy-v1'),'usage',jsonb_build_object('model','fixture-model','promptTokens',40,'completionTokens',50));
update fixture set receipt=jsonb_build_object('status','received','providerId','fixture-completion','content',(classification-'policy'-'provenance'-'usage')::text,'usage',classification->'usage');
create function pg_temp.selection_input() returns jsonb language sql as $$select '{"scope":"unanalyzed_current","reason":"Review the full property selection"}'::jsonb$$;
create function pg_temp.control_input(op text) returns jsonb language sql as $$select jsonb_build_object('batchId',f.batch_id,'expectedVersion',b.version,'operation',op,'reason','Reviewed exact selected source versions')||case when op='approve' then jsonb_build_object('maxModelCalls',b.selection_count) else '{}'::jsonb end from fixture f join public.reviewflow_analysis_batches b on b.id=f.batch_id$$;
create function pg_temp.item(pos integer) returns public.reviewflow_analysis_batch_items language sql as $$select i from public.reviewflow_analysis_batch_items i join fixture f on f.batch_id=i.batch_id where i.position=pos$$;

do $$declare f fixture;command uuid:=gen_random_uuid();collision uuid:=gen_random_uuid();begin select * into f from fixture;
 perform public.append_shared_action_event(collision,collision,f.property_id,f.actor_id,'reviewflow','review.analysis.requested','server_confirmed','succeeded','{}',null,null,'{}');
 begin
  perform public.prepare_reviewflow_batch(collision,f.property_id,f.actor_id,pg_temp.selection_input(),f.model_template);
  raise exception 'Expected action collision';
 exception when others then if sqlerrm='Expected action collision' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.reviewflow_analysis_batches where id=collision) and not exists(select 1 from public.reviewflow_analysis_batch_items where batch_id=collision) and not exists(select 1 from public.shared_jobs where id=collision),'failed action evidence rolls back the complete saved selection');
end$$;

do $$declare f fixture;r jsonb;payload jsonb;command uuid:=gen_random_uuid();i public.reviewflow_analysis_batch_items;begin select * into f from fixture;
 perform pg_temp.check(not has_table_privilege('authenticated','public.reviewflow_analysis_batches','select') and not has_table_privilege('authenticated','public.reviewflow_analysis_batch_items','update'),'batch source evidence is server-private');
 perform pg_temp.check(not has_function_privilege('authenticated','public.prepare_reviewflow_batch(uuid,uuid,uuid,jsonb,jsonb)','execute') and not has_function_privilege('authenticated','public.append_reviewflow_service_event(uuid,uuid,text,text,text,jsonb,jsonb,jsonb,jsonb)','execute'),'browser cannot authorize a queue or fabricate system outcomes');
 perform pg_temp.check(public.prepare_reviewflow_batch(f.batch_id,f.property_id,gen_random_uuid(),pg_temp.selection_input(),f.model_template)->>'state'='forbidden','selection requires actual current property access');
 r:=public.prepare_reviewflow_batch(f.batch_id,f.property_id,f.actor_id,pg_temp.selection_input(),f.model_template);
 perform pg_temp.check(r->>'state'='prepared' and r->>'selected'='105','full selection includes reviews beyond the former first100 limit');
 perform pg_temp.check(public.prepare_reviewflow_batch(f.batch_id,f.property_id,f.actor_id,pg_temp.selection_input(),'{}')->>'batchId'=f.batch_id::text,'lost selection reply reuses the original saved model recipe');
 perform pg_temp.check(public.prepare_reviewflow_batch(gen_random_uuid(),f.property_id,f.actor_id,pg_temp.selection_input(),f.model_template)->>'state'='busy','overlapping active queues return the saved selection');
 insert into public.reviews(property_id,platform,platform_review_id,review_text) values(f.property_id,'other','arrived-later','A later review');
 perform pg_temp.check((select count(*)=105 from public.reviewflow_analysis_batch_items where batch_id=f.batch_id),'later reviews do not expand a reviewed selection');
 i:=pg_temp.item(1);perform pg_temp.check(public.prepare_reviewflow_batch_item(f.batch_id,i.id)->>'state'='authority_required','preparation alone does not grant model execution');
 perform pg_temp.check(public.decide_reviewflow_batch(command,f.property_id,gen_random_uuid(),pg_temp.control_input('approve'))->>'state'='manager_required','unknown actor cannot approve model work');
 perform pg_temp.check(public.decide_reviewflow_batch(command,f.property_id,f.actor_id,pg_temp.control_input('approve')||'{"maxModelCalls":100}')->>'state'='scope_confirmation_required','approval must confirm the exact selected model-call bound');
 payload:=pg_temp.control_input('approve');perform pg_temp.check(public.decide_reviewflow_batch(command,f.property_id,f.actor_id,payload)->>'state'='saved' and public.decide_reviewflow_batch(command,f.property_id,f.actor_id,payload)->>'state'='replayed','scope approval survives a lost response once');
 perform pg_temp.check((select count(*)=0 from public.reviewflow_analysis_requests where property_id=f.property_id),'approval does not itself call or create a model request');
 perform pg_temp.check(jsonb_array_length(public.next_reviewflow_batch_items(f.batch_id,200))=20,'worker selection is bounded without truncating the saved queue');
 perform pg_temp.check(public.begin_reviewflow_analysis(i.id,f.property_id,f.actor_id,jsonb_build_object('reviewId',i.review_id,'sourceVersion',i.source_version),public.reviewflow_batch_model_input(f.model_template||'{"model":"changed-model"}',i.source_snapshot))->>'state'='batch_input_changed','a direct child request cannot substitute a different approved model recipe');
 r:=public.prepare_reviewflow_batch_item(f.batch_id,i.id);
 perform pg_temp.check(r->>'state'='linked' and r->>'requestId'=i.id::text and r->'ownsRequest'='true'::jsonb,'owned child identity is stable and linked atomically');
 perform pg_temp.check(public.prepare_reviewflow_batch_item(f.batch_id,i.id)->>'requestId'=i.id::text,'replayed child preparation cannot create another analysis request');
 perform pg_temp.check((select actor_id is null and service_principal='reviewflow.batch' from public.shared_action_events where id=i.id),'automatic child creation is attributed to the queue service');
 perform pg_temp.check((select model_input=public.reviewflow_batch_model_input(f.model_template,i.source_snapshot) from public.reviewflow_analysis_requests where id=i.id),'each child keeps the approved recipe and original source');
end$$;

do $$declare f fixture;i public.reviewflow_analysis_batch_items;claim jsonb;result jsonb;c jsonb;begin select * into f from fixture;i:=pg_temp.item(1);claim:=public.claim_reviewflow_analysis(i.id);
 perform pg_temp.check(claim->>'state'='invoke_once' and public.claim_reviewflow_analysis(i.id)->>'state'='running','concurrent batch workers cannot invoke one child twice');
 perform pg_temp.check(not exists(select 1 from jsonb_array_elements(public.next_reviewflow_batch_items(f.batch_id,20)) e where e->>'itemId'=i.id::text),'uncertain running work does not block later selected reviews or get invoked again');
 perform public.record_reviewflow_analysis_result(i.id,(claim->>'claimToken')::uuid,f.receipt);
 result:=public.apply_reviewflow_analysis(i.id,f.property_id,f.actor_id,jsonb_build_object('resultHash',(select result_hash from public.reviewflow_analysis_requests where id=i.id),'analysis',f.classification));
 perform pg_temp.check(result->>'state'='saved','saved child result applies through the existing evidence contract');
 result:=public.checkpoint_reviewflow_batch(f.batch_id);
 perform pg_temp.check(result->'summary'->>'analyzed'='1' and result->'summary'->>'pending'='104','checkpoint reports actual analysis and remaining selected work');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where property_id=f.property_id and action='review.analysis.completed' and actor_id is null and service_principal='reviewflow.analysis'),'model completion has its actual system identity');
 perform pg_temp.check(public.checkpoint_reviewflow_batch(f.batch_id)=result,'unchanged checkpoint is a stable read of saved progress');
 i:=pg_temp.item(2);perform public.prepare_reviewflow_batch_item(f.batch_id,i.id);claim:=public.claim_reviewflow_analysis(i.id);perform public.record_reviewflow_analysis_result(i.id,(claim->>'claimToken')::uuid,f.receipt);
 c:=jsonb_set(f.classification,'{policy,requiresHumanReview}','true');perform public.apply_reviewflow_analysis(i.id,f.property_id,f.actor_id,jsonb_build_object('resultHash',(select result_hash from public.reviewflow_analysis_requests where id=i.id),'analysis',c));
 result:=public.checkpoint_reviewflow_batch(f.batch_id);perform pg_temp.check(result->'summary'->>'staffReview'='1' and result->'summary'->>'analyzed'='1','staff-review classification is not reported as ordinary completed analysis');
 i:=pg_temp.item(3);update public.reviews set review_text='The selected source changed' where id=i.review_id;perform pg_temp.check(public.prepare_reviewflow_batch_item(f.batch_id,i.id)->>'state'='held','source changes hold their selected item without consuming a model request');
 perform pg_temp.check(not exists(select 1 from public.reviewflow_analysis_requests where id=i.id),'stale source creates no child invocation');
end$$;

do $$declare f fixture;i public.reviewflow_analysis_batch_items;borrowed public.reviewflow_analysis_batch_items;external_id uuid:=gen_random_uuid();claim jsonb;payload jsonb;command uuid:=gen_random_uuid();begin select * into f from fixture;
 borrowed:=pg_temp.item(4);perform public.begin_reviewflow_analysis(external_id,f.property_id,f.actor_id,jsonb_build_object('reviewId',borrowed.review_id,'sourceVersion',borrowed.source_version),public.reviewflow_batch_model_input(f.model_template,borrowed.source_snapshot));perform public.prepare_reviewflow_batch_item(f.batch_id,borrowed.id);
 perform pg_temp.check(not exists(select 1 from jsonb_array_elements(public.next_reviewflow_batch_items(f.batch_id,20)) e where e->>'itemId'=borrowed.id::text),'independently queued work cannot starve later batch-owned items');
 perform pg_temp.check((select analysis_request_id=external_id and owns_request=false from public.reviewflow_analysis_batch_items where id=borrowed.id),'independent active analysis retains its identity');
 i:=pg_temp.item(5);perform public.prepare_reviewflow_batch_item(f.batch_id,i.id);claim:=public.claim_reviewflow_analysis(i.id);payload:=pg_temp.control_input('stop');
 perform pg_temp.check(public.decide_reviewflow_batch(command,f.property_id,f.actor_id,payload)->>'state'='saved' and public.decide_reviewflow_batch(command,f.property_id,f.actor_id,payload)->>'state'='replayed','queue stop and owned child stops recover a lost reply');
 perform pg_temp.check((select state='queued' from public.reviewflow_analysis_requests where id=external_id),'stopping a batch does not cancel independently requested analysis');
 perform pg_temp.check((select state='stopped' from public.reviewflow_analysis_requests where id=i.id),'batch-owned unfinished work is stopped');
 perform public.record_reviewflow_analysis_result(i.id,(claim->>'claimToken')::uuid,f.receipt);
 perform pg_temp.check((select state='stopped' and raw_result=f.receipt from public.reviewflow_analysis_requests where id=i.id),'late result remains recorded after stopping its queue');
 perform pg_temp.check(public.apply_reviewflow_analysis(i.id,f.property_id,f.actor_id,jsonb_build_object('resultHash',(select result_hash from public.reviewflow_analysis_requests where id=i.id),'analysis',f.classification))->>'state'='stopped','late stopped model result cannot mutate the review case');
 perform pg_temp.check((select summary->>'pending'='0' and summary->>'stopped'='102' and summary->>'analyzed'='1' and summary->>'staffReview'='1' and summary->>'held'='1' from public.reviewflow_analysis_batches where id=f.batch_id),'stopped queue retains truthful complete counts');
 perform pg_temp.check(jsonb_array_length(public.next_reviewflow_batch_items(f.batch_id,5))=0,'stopped work is no longer eligible for execution');
end$$;

do $$declare f fixture;new_batch uuid:=gen_random_uuid();i public.reviewflow_analysis_batch_items;organization uuid:=gen_random_uuid();result jsonb;begin select * into f from fixture;
 result:=public.prepare_reviewflow_batch(new_batch,f.property_id,f.actor_id,pg_temp.selection_input(),f.model_template);perform pg_temp.check(result->>'selected'='104','new selection excludes both kinds of saved current analysis and includes later reviews');
 update fixture set batch_id=new_batch;perform public.decide_reviewflow_batch(gen_random_uuid(),f.property_id,f.actor_id,pg_temp.control_input('approve'));i:=pg_temp.item(1);perform public.prepare_reviewflow_batch_item(new_batch,i.id);
 update public.profiles set role='viewer' where id=f.actor_id;
 result:=public.checkpoint_reviewflow_batch(new_batch);perform pg_temp.check(result->>'state'='needs_review' and result->'summary'->>'pending'='0' and result->'summary'->>'held'='104','revoked fixture manager authority holds all remaining queue work');
 perform pg_temp.check(public.claim_reviewflow_analysis(i.id)->>'state'='held','saved child cannot execute after its approval loses scope');
 perform pg_temp.check((select state='held' from public.reviewflow_analysis_requests where id=i.id),'scope loss preserves an explicit held child');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where property_id=f.property_id and action='review.batch.progressed' and shared_action_events.result->>'requestState'='needs_review' and actor_id is null),'scope loss records its actual system outcome under saved job ownership');
end$$;
select count(*) as passed_assertions from checks;
rollback;
